"""Parity against the goldens generated by the canonical PHP SDK.

The same JSON files are used by the Go and Node ports, so all four languages compare against one
source of truth: if the PHP builder changes shape, every port fails at once.
"""

import json
from pathlib import Path

from src.builder.care_team import CareTeamBuilder
from src.builder.coverage import CoverageBuilder
from src.builder.endpoint import EndpointBuilder
from src.builder.healthcare_service import HealthcareServiceBuilder
from src.builder.related_person import RelatedPersonBuilder

GOLDEN = Path(__file__).parent / "testdata"


def golden(nama: str) -> dict:
    return json.loads((GOLDEN / f"{nama}_php_golden.json").read_text())


def test_healthcare_service_matches_php_payload():
    b = (
        HealthcareServiceBuilder()
        .set_id("hs-1")
        .add_identifier(
            "http://sys-ids.kemkes.go.id/healthcareservice/1", "1", "official", "PRN", None
        )
        .set_status("active")
        .set_name("Poli Umum")
        .set_type("http://terminology.hl7.org/CodeSystem/service-type", "124", "General Practice")
        .set_type("http://terminology.hl7.org/CodeSystem/service-type", "125", "General Practice 2")
        .set_location("Location/1000000003", "Poli Umum Lt. 1")
        .set_provided_by("Organization/1000000001", None)
    )
    assert b.build() == golden("healthcare_service")


def test_endpoint_matches_php_payload():
    b = (
        EndpointBuilder()
        .set_id("end-1")
        .add_identifier("http://sys-ids.kemkes.go.id/endpoint/1", "end-1")
        .add_identifier("urn:oid:1.2.3", "alt-1")
        .set_status("active")
        .set_connection_type("hl7-fhir-rest", "HL7 FHIR")
        .set_name("Endpoint SATUSEHAT")
        .set_managing_organization("1000000001", "RS Contoh")
        .add_contact("phone", "0254000002", "work")
        .set_period("2026-01-01")
        .add_payload_type("any", "Any")
        .add_payload_mime_type("application/fhir+json")
        .set_address("https://api.satusehat.kemkes.go.id/fhir-r4/v1")
        .add_header("Authorization: Bearer x")
    )
    assert b.build() == golden("endpoint")


def test_care_team_matches_php_payload():
    b = (
        CareTeamBuilder()
        .set_id("ct-1")
        .add_identifier("urn:oid:1.2.3", "ct-1", "official", "PRN", None)
        .set_status("active")
        .set_code({"coding": [{"system": "http://snomed.info/sct", "code": "768242006", "display": "Care team"}]})
        .set_subject("Patient/1000000001", "Budi Santoso")
        .set_encounter("Encounter/2000000001")
    )
    assert b.build() == golden("care_team")


def test_related_person_matches_php_payload():
    b = (
        RelatedPersonBuilder()
        .set_id("rp-1")
        .add_identifier("http://sys-ids.kemkes.go.id/relatedperson/1000000001", "rp-1")
        .set_active(True)
        .set_patient("1000000001", "Budi Santoso")
        .add_relationship("SPS", "Spouse")
        .add_relationship("CHILD")
        .add_name({"text": "Yessike", "family": "Yessike"})
        .add_telecom("phone", "081211112222")
        .add_address({"line": ["Jl. Contoh No. 2"], "city": "Serang"})
        .add_communication("id-ID", True)
        .set_gender("female")
        .set_birth_date("1990-02-02")
        .add_extension(
            "https://fhir.kemkes.go.id/r4/StructureDefinition/relatedperson-is-guardian", True
        )
    )
    assert b.build() == golden("related_person")


def test_coverage_matches_php_payload():
    b = (
        CoverageBuilder()
        .set_id("cov-1")
        .add_identifier("http://sys-ids.kemkes.go.id/coverage/1000000001", "cov-1")
        .set_status("active")
        .set_type(
            "http://terminology.hl7.org/CodeSystem/v3-ActCode", "EHCPOL", "extended healthcare"
        )
        .set_policy_holder("Patient/1000000001")
        .set_subscriber("Patient/1000000001")
        .set_subscriber_id("BPJS-0001")
        .set_beneficiary("Patient/1000000001")
        .set_dependent("1")
        .set_relationship("http://terminology.hl7.org/CodeSystem/subscriber-relationship", "self")
        .add_payor("Organization/1000000001", "BPJS Kesehatan")
        .set_class(
            "http://terminology.hl7.org/CodeSystem/coverage-class", "group", "GRP-1", "Grup A"
        )
        .set_order(1)
        .set_network("JKN")
        .set_cost_to_beneficiary(50000.0, "IDR")
        .set_period("2026-01-01", "2026-12-31")
    )
    assert b.build() == golden("coverage")
